function CardProgressionEquipmentLadderRiseFinishNode:RefreshQuality()
    local beforeQuality = EquipUtils.GetQuality(self._befDojo)
    local afterQuality = EquipUtils.GetQuality(self._curDojo)

    self.ImgIconBgBefore.Status = beforeQuality
    self.ImgIcon2Before.Status = beforeQuality
    self.ImgIconBgAfter.Status = afterQuality
    self.ImgIcon2After.Status = afterQuality
end

---刷新装备道具
function CardProgressionEquipmentLadderRiseFinishNode:RefreshEquipmentGoods()
    local dojo = self:GetCurDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(dojo.equipmentId)
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    -- CfUtils.SetUISwitchImage(self.ImgFurnace, goodsVo.quality)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = dojo, goodsId = dojo.equipmentId, isShowNo = false})
    end
    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
end



---刷新属性
function CardProgressionEquipmentLadderRiseFinishNode:RefreshAttr()
    local dojo = self:GetCurDojo()
    local attrs = dojo:GetLadderRiseAttrs()
    for index, value in ipairs(attrs) do
        ---@type CardProgressionEquipmentNumericalValue
        local env = self:GetSubAttrEnv(index)
        CfUtils.SetActive(env.controller.gameObject, true)
        if isNotNull(env) then
            env:RefreshUI(attrs[index], index, dojo)
        end
    end
end

---显示战力变化
function CardProgressionEquipmentLadderRiseFinishNode:ShowPointChange()
    local befDojo = self:GetBefDojo()
    if checkInt(befDojo.playerCardId) == 0 then return end

    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(befDojo.playerCardId)
    local entity = CardProgressionUtils.GenerateEntityByCardDojo(cardDojo)
    local curPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    for k, v in pairs(entity.equipPart2Dojo) do
        if checkInt(v.id) == checkInt(befDojo.id) then
            entity.equipPart2Dojo[k] = befDojo
            break
        end
    end
    local befPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    CardProgressionUtils.ChangePointToast(curPoint - befPoint)
end

---获取befDojo
---@return EquipDojo
function CardProgressionEquipmentLadderRiseFinishNode:GetBefDojo()
    return self._befDojo
end

---获取curDojo
---@return EquipDojo
function CardProgressionEquipmentLadderRiseFinishNode:GetCurDojo()
    return self._curDojo
end

---@return CardProgressionEquipmentNumericalValue
function CardProgressionEquipmentLadderRiseFinishNode:GetSubAttrEnv(i)
    local env = self.attrNodeEnvs[i]
    if env == nil then
        local node
        if i == 1 then
            node = self.ATKNumericalValue
        else
            node = self.NumericalUnlock.gameObject:AddChild(self.ATKNumericalValue.gameObject)
        end
        env = CfUtils.GetLuaScr(node, "Game.CardProgression.Equip.CardProgressionEquipmentNumericalValue")
        self.attrNodeEnvs[i] = env
    end
    return env
end
